#!/bin/sh
# Chat15 NAS start-up: create the fixed Unix/Samba accounts from secret files
# mounted read-only at /run/nas-secrets/<account> (one password per file,
# generated by poc/sync-nas/create-secrets.mjs, never printed), create the share
# directories with group ownership, then run smbd in the foreground.
set -eu
SECRETS=/run/nas-secrets

ensure_group() { getent group "$1" >/dev/null 2>&1 || addgroup -S "$1"; }
ensure_user() {
  # $1 account, $2 primary group
  id "$1" >/dev/null 2>&1 || adduser -S -D -H -s /sbin/nologin -G "$2" "$1"
  pw="$(cat "$SECRETS/$1")"
  [ "${#pw}" -ge 24 ] || { echo "secret for $1 too short" >&2; exit 1; }
  printf '%s\n%s\n' "$pw" "$pw" | smbpasswd -a -s "$1" >/dev/null
  smbpasswd -e "$1" >/dev/null
  unset pw
}

ensure_group nas-team-a
ensure_group nas-team-b
ensure_group nas-outsiders
ensure_user svc-nc-team-a nas-team-a
ensure_user nas-member-a nas-team-a
ensure_user svc-nc-team-b nas-team-b
ensure_user nas-manager-b nas-team-b
ensure_user nas-outsider nas-outsiders

for team in team-a team-b; do
  mkdir -p "/srv/nas/$team"
  chown root:"nas-$team" "/srv/nas/$team"
  chmod 2770 "/srv/nas/$team"
done
mkdir -p /var/log/samba
exec smbd --foreground --no-process-group --debug-stdout
